"""Game data, generated by scripts/data/build_world_data.py from the dumps in docs/game ids."""

import json
import pkgutil
from dataclasses import dataclass, field
from typing import Optional

_DATA = json.loads(pkgutil.get_data(__name__, "gt2.json").decode("utf-8"))

# Manufacturer IDs (docs/game ids/manufacturers.md), without Vauxhall (#35), whose dealership is
# never shown
MANUFACTURERS: dict[str, int] = {
    "Acura": 0, "Alfa Romeo": 1, "Aston Martin": 2, "Audi": 3, "BMW": 4, "Chevrolet": 5,
    "Citroen": 6, "Daihatsu": 7, "Dodge": 8, "FIAT": 9, "Ford": 10, "Honda": 11, "Jaguar": 13,
    "Lancia": 14, "Lister": 16, "Lotus": 17, "Mazda": 18, "Mercedes-Benz": 19, "Mini & MG": 21,
    "Mitsubishi": 22, "Nissan": 23, "Opel": 24, "Peugeot": 25, "Plymouth": 26, "Renault": 27,
    "RUF": 28, "Shelby": 29, "Subaru": 30, "Suzuki": 31, "Tommy kaira": 32, "Toyota": 33,
    "TVR": 34, "Vector": 36, "Venturi": 37, "Volkswagen": 38,
}

LICENSES = ["B", "A", "IC", "IB", "IA", "S"]  # tier 1 to 6, in Progressive License order
LICENSE_TESTS = 10


@dataclass(frozen=True)
class Car:
    code: str
    name: str
    maker: str
    price: int
    drive: str
    power: int
    turbo: bool  # stock turbo engine
    parts: dict[int, tuple[int, int]]  # power part ID -> (price, power gain on its own)
    rm: bool
    rm_price: Optional[int]
    rm_gain: int
    dirt: bool
    dirt_price: Optional[int]


@dataclass(frozen=True)
class Event:
    index: int
    code: str
    name: str
    category: str  # race, rally, endurance, one_make, synthesizer
    league: Optional[str]  # regional, pro, world
    tier: int  # Progressive Licenses needed
    drive: Optional[str]
    turbo: Optional[str]  # no_turbo, turbo_required
    racing_mod: Optional[str]  # no_racing_mod, racing_mod_required
    max_power: Optional[int]
    allowed_cars: tuple[str, ...] = field(default=())
    prize: int = 0


CARS: dict[str, Car] = {
    code: Car(code, c["name"], c["maker"], c["price"], c["drive"], c["power"], c["turbo"],
              {int(pid): (v[0], v[1]) for pid, v in c["parts"].items()},
              c["rm"], c["rmPrice"], c["rmGain"], c["dirt"], c["dirtPrice"])
    for code, c in _DATA["cars"].items()
}

EVENTS: list[Event] = [
    Event(e["index"], e["code"], e["name"], e["category"], e["league"], e["tier"], e["drive"],
          e["turbo"], e["racingMod"], e["maxPower"], tuple(e["allowedCars"]), e["prize"])
    for e in _DATA["events"]
]
EVENTS_BY_CODE: dict[str, Event] = {e.code: e for e in EVENTS}
